import os
import json
from datetime import datetime
from typing import List, Dict, Any

# Directory paths
CONVERSATIONS_DIR = "/mnt/data/conversations"
NORMALIZED_DIR = "/mnt/data/normalized_conversations"

# Ensure normalized output directory exists
os.makedirs(NORMALIZED_DIR, exist_ok=True)

def normalize_role(input_role: str) -> str:
    ROLE_MAP = {
        "user": "User",
        "assistant": "AI Partner",
        "system": "System"
    }
    return ROLE_MAP.get(input_role, input_role) if input_role else input_role

def format_timestamp(ts: float) -> str:
    try:
        return datetime.utcfromtimestamp(ts).isoformat()
    except Exception:
        return ""

def is_message(value: Any) -> bool:
    if not isinstance(value, dict):
        return False
    message = value.get("message")
    if not isinstance(message, dict):
        return False
    author = message.get("author")
    content = message.get("content")
    return (
        isinstance(author, dict) and "role" in author and
        isinstance(content, dict) and isinstance(content.get("parts"), list) and content["parts"]
    )

def convert_conversation_to_messages(conversation: Dict[str, Any]) -> List[Dict[str, Any]]:
    mapping = conversation.get("mapping", {})
    nodes = [node for node in mapping.values() if is_message(node)]
    nodes.sort(key=lambda node: node["message"].get("create_time") or 0)
    messages = []
    for node in nodes:
        message = node["message"]
        content_parts = message["content"].get("parts", [])
        content = "\n".join(content_parts).strip()
        if content:
            create_time = message.get("create_time", 0.0)
            messages.append({
                "role": normalize_role(message["author"]["role"]),
                "flattened": content,
                "parts": content_parts,
                "id": message["id"],
                "create_time": create_time,
                "timestamp": format_timestamp(create_time)
            })
    return messages

# Discover and process unnormalized conversation files
normalized_files = set(os.listdir(NORMALIZED_DIR))
processed = []

for root, _, files in os.walk(CONVERSATIONS_DIR):
    for file in files:
        if file.endswith(".json"):
            conv_path = os.path.join(root, file)
            norm_filename = os.path.splitext(file)[0] + ".normalized.json"
            norm_path = os.path.join(NORMALIZED_DIR, norm_filename)

            if os.path.exists(norm_path):
                continue  # already normalized

            try:
                with open(conv_path, "r", encoding="utf-8") as f:
                    conversation = json.load(f)
                messages = convert_conversation_to_messages(conversation)
                with open(norm_path, "w", encoding="utf-8") as out:
                    json.dump(messages, out, indent=2, ensure_ascii=False)
                processed.append(file)
            except Exception as e:
                print(f"Failed to process {file}: {e}")

import ace_tools as tools; tools.display_dataframe_to_user(name="Normalized Files", dataframe={"Normalized": processed})

